-- Seed: form rules + PM terms from the PM Pricing Info sheet (rule 14)
-- Generated by sql/forms/generate_form_seed.py on 2026-09-06 from Copy of PM Pricing Info.xlsx.
-- Do not hand-edit: change the workbook or the generator and regenerate.
-- Requires create_form_tables.sql. Safe to re-run (see the notes in each block).

-- One FormRule + PMRule per sheet row, matched case-insensitively on call center + company name (aliases in the generator).
-- Rows whose pairing does not exist are PRINTed and skipped; rows that already have a rule are left untouched.
-- Blank pricing rows still get a rule (billing mode NULL) so the tab has somewhere to put the team's answers.
SET NOCOUNT ON;
DECLARE @t_id INT = (SELECT TOP 1 t_id FROM dbo.Trade WHERE t_trade = N'HVAC' AND t_id_parent IS NULL);
DECLARE @ft_id INT = (SELECT TOP 1 ft_id FROM dbo.FormTemplate WHERE t_id = @t_id AND ft_active = 1 ORDER BY ft_version DESC);
IF @t_id IS NULL OR @ft_id IS NULL BEGIN RAISERROR('HVAC trade or active HVAC PM template not found - run seed_form_template_hvac.sql first', 16, 1); RETURN; END;
DECLARE @pmbm_setnte INT = (SELECT pmbm_id FROM dbo.PMBillingMode WHERE pmbm_mode = 'SetNte');
DECLARE @pmbm_tiered INT = (SELECT pmbm_id FROM dbo.PMBillingMode WHERE pmbm_mode = 'ContractTiered');
DECLARE @xccc_id INT, @fr_id INT, @pmr_id INT, @inserted INT = 0, @skipped INT = 0, @existing INT = 0;

-- Boss / Aveda
SET @xccc_id = (SELECT TOP 1 x.xccc_id FROM dbo.xrefCompanyCallCenter x JOIN dbo.CallCenter cc ON cc.cc_id = x.cc_id JOIN dbo.Company c ON c.c_id = x.c_id
                WHERE LOWER(LTRIM(RTRIM(cc.cc_name))) = LOWER(N'Boss Facility Services Inc') AND LOWER(LTRIM(RTRIM(c.c_name))) = LOWER(N'Aveda') ORDER BY x.xccc_active DESC, x.xccc_id);
IF @xccc_id IS NULL BEGIN PRINT 'SKIP (no company pairing): Boss / Aveda'; SET @skipped += 1; END
ELSE IF EXISTS (SELECT 1 FROM dbo.FormRule WHERE xccc_id = @xccc_id AND t_id = @t_id) BEGIN SET @existing += 1; END
ELSE BEGIN
    INSERT INTO dbo.FormRule (xccc_id, t_id, ft_id, fr_note) VALUES (@xccc_id, @t_id, @ft_id, N'Seeded from PM Pricing Info sheet (2026-09-06) | Pricing contract attachment in Evo: NO');
    SET @fr_id = SCOPE_IDENTITY();
    INSERT INTO dbo.PMRule (fr_id, pmbm_id, pmr_nteguideline, pmr_firsttimerule, pmr_pricingnote, pmr_filtersincluded, pmr_nofilterchange, pmr_freefilters, pmr_freebeltchangesperyear, pmr_beltschargeable, pmr_customerform, pmr_customerformnote, pmr_submissiondestination, pmr_contactname, pmr_contactemail)
        VALUES (@fr_id, @pmbm_setnte, N'MatchSetNte', NULL, N'Everything task listed in SOW is included in the NTE set price for PM, your final billing cost should match the Set NTE.', NULL, NULL, NULL, NULL, NULL, N'CustomerPdfForm', N'Provided by boss', NULL, NULL, NULL);
    SET @pmr_id = SCOPE_IDENTITY();
    SET @inserted += 1;
END;

